package com.example.aura_style

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.tooling.preview.Preview
import com.example.aura_style.ui.theme.Aura_StyleTheme
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            Aura_StyleTheme {
                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
                    Greeting(
                        name = "Android",
                        modifier = Modifier.padding(innerPadding)
                    )
                }
            }
        }
    }
}

@Composable
fun Greeting(name: String, modifier: Modifier = Modifier) {
    Text(
        text = "Hello $name!",
        modifier = modifier
    )
}

@Preview(showBackground = true)
@Composable
fun GreetingPreview() {
    Aura_StyleTheme {
        Greeting("Android")
    }
}

package com.example.aura_style

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.viewModels
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import com.example.aura_style.ui.screen.LoginScreen
import com.example.aura_style.ui.screen.RegistrationScreen
import com.example.aura_style.ui.theme.Aura_StyleTheme
import com.example.aura_style.ui.viewmodel.UserViewModel
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    private val userViewModel: UserViewModel by viewModels()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            var showRegistration by rememberSaveable { mutableStateOf(false) }

            Aura_StyleTheme {
                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
                    if (showRegistration) {
                        RegistrationScreen(
                            userViewModel = userViewModel,
                            onBackToLoginClick = { showRegistration = false },
                            modifier = Modifier.padding(innerPadding)
                        )
                    } else {
                        LoginScreen(
                            userViewModel = userViewModel,
                            onSignUpClick = { showRegistration = true },
                            modifier = Modifier.padding(innerPadding)
                        )
                    }
                }
            }
        }
    }
}

package com.example.aura_style.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.aura_style.data.local.entity.User
import com.example.aura_style.data.repository.UserRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

@HiltViewModel
class UserViewModel @Inject constructor(
    private val userRepository: UserRepository
) : ViewModel() {
    private val _user = MutableStateFlow<User?>(null)
    val user: StateFlow<User?> = _user.asStateFlow()

    fun insertUser(user: User) {
        viewModelScope.launch {
            userRepository.insertUser(user)
            _user.value = userRepository.getUserByEmail(user.email)
        }
    }

    fun getUserByEmail(email: String) {
        viewModelScope.launch {
            _user.value = userRepository.getUserByEmail(email)
        }
    }

    fun deleteUser(user: User) {
        viewModelScope.launch {
            userRepository.deleteUser(user)
            if (_user.value?.id == user.id) {
                _user.value = null
            }
        }
    }
}

package com.example.aura_style.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.aura_style.data.local.entity.User
import com.example.aura_style.data.repository.UserRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

@HiltViewModel
class UserViewModel @Inject constructor(
    private val userRepository: UserRepository
) : ViewModel() {
    private val _user = MutableStateFlow<User?>(null)
    val user: StateFlow<User?> = _user.asStateFlow()

    private val _authMessage = MutableStateFlow("")
    val authMessage: StateFlow<String> = _authMessage.asStateFlow()

    fun insertUser(email: String, password: String) {
        if (email.isBlank() || password.isBlank()) {
            _authMessage.value = "Email and password are required"
            return
        }

        viewModelScope.launch {
            val user = User(email = email.trim(), password = password)
            userRepository.insertUser(user)
            _user.value = userRepository.getUserByEmail(user.email)
            _authMessage.value = "Registration successful"
        }
    }

    fun getUserByEmail(email: String, passwordToCheck: String? = null) {
        if (email.isBlank()) {
            _authMessage.value = "Email is required"
            return
        }

        viewModelScope.launch {
            val foundUser = userRepository.getUserByEmail(email.trim())
            _user.value = foundUser

            if (passwordToCheck != null) {
                _authMessage.value = when {
                    foundUser == null -> "User not found"
                    foundUser.password == passwordToCheck -> "Login successful"
                    else -> "Invalid password"
                }
            }
        }
    }

    fun deleteUser(user: User) {
        viewModelScope.launch {
            userRepository.deleteUser(user)
            if (_user.value?.id == user.id) {
                _user.value = null
                _authMessage.value = "User deleted"
            }
        }
    }
}
